const byId = new Map(MEDIA_ASSETS.map((m) => [m.id, m]))
export function mediaAssetById(id: string): MediaAsset | undefined {
  return byId.get(id)
}

/**
 * A slot is what a lesson references. Assets can be swapped behind a slot
 * without editing any lesson. The first approved asset in `assetIds` renders.
 */
export type MediaSlot = {
  id: string
  title: string
  /** What the missing visual needs to show, in plain words, for the pending panel. */
  need: string
  assetIds: string[]
}

